import{_ as t,C as r,o as s,c,a1 as o,E as d}from"./chunks/framework.DceXOx8u.js";const g=JSON.parse('{"title":"Arquitectura","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/es/guide/arquitectura"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/es/guide/arquitectura"}]]},"headers":[],"relativePath":"es/guide/arquitectura.md","filePath":"es/guide/arquitectura.md"}'),n={name:"es/guide/arquitectura.md"};function i(l,e,u,p,h,m){const a=r("Mermaid");return s(),c("div",null,[e[0]||(e[0]=o('<h1 id="arquitectura" tabindex="-1">Arquitectura <a class="header-anchor" href="#arquitectura" aria-label="Permalink to &quot;Arquitectura&quot;">​</a></h1><p>Cómo está montado <code>@botmesh/core</code>: las capas de paquetes, los módulos que hay detrás de la clase <code>Bot</code>, el camino de un mensaje de entrada y de salida, y dónde se enchufan las funciones opcionales (durabilidad, coordinación entre réplicas, scheduler durable, trazas). No necesitas nada de esto para escribir un bot. Es para quien extiende el core, escribe un canal o un store, o depura lo que pasa entre el provider y un handler.</p><h2 id="capas" tabindex="-1">Capas <a class="header-anchor" href="#capas" aria-label="Permalink to &quot;Capas&quot;">​</a></h2><p>El framework es un monorepo pnpm. Las dependencias solo van <strong>hacia abajo</strong>:</p><table tabindex="0"><thead><tr><th>Capa</th><th>Paquetes</th></tr></thead><tbody><tr><td>Motor</td><td><code>@botmesh/core</code> (su única dependencia runtime es <code>pino</code>)</td></tr><tr><td>Infra compartida</td><td><code>@botmesh/http</code> (cliente anti-SSRF), <code>@botmesh/graph-core</code> (helpers de Meta Graph), <code>@botmesh/wa-gateway-kit</code> (identidad, REST y media comunes a Evolution y WPPConnect), <code>@botmesh/server</code> (ingress de webhooks)</td></tr><tr><td>Canales</td><td><code>@botmesh/baileys</code>, <code>@botmesh/meta</code>, <code>@botmesh/telegram</code>, … (cada uno implementa <code>IProvider</code>)</td></tr><tr><td>Stores</td><td><code>@botmesh/sqlite-store</code>, <code>@botmesh/redis-store</code>, … (cada uno implementa <code>IStore</code>)</td></tr><tr><td>Plugins / producto</td><td><code>@botmesh/ai</code>, <code>nlu</code>, <code>manager</code>, <code>inbox</code>, …</td></tr></tbody></table><p>El core es <strong>agnóstico de transporte</strong>. No sabe nada de JIDs, códigos QR ni webhooks: los ids de chat, usuario y mensaje son strings opacos que nunca parsea, y el provider resuelve los alias de identidad (LID/PN en WhatsApp, <code>sender_chat</code> en Telegram) <strong>antes</strong> de emitir el evento, así que la misma persona llega siempre con el mismo <code>senderId</code>. Todo lo específico de un canal vive en el paquete del canal.</p><h2 id="dentro-del-bot" tabindex="-1">Dentro del <code>Bot</code> <a class="header-anchor" href="#dentro-del-bot" aria-label="Permalink to &quot;Dentro del `Bot`&quot;">​</a></h2><p><code>Bot</code> es una <strong>fachada</strong> fina: sus métodos llevan la documentación pública y delegan. El motor vive en <code>packages/core/src/core/bot/</code>:</p><table tabindex="0"><thead><tr><th>Módulo</th><th>Responsabilidad</th></tr></thead><tbody><tr><td><code>compose.ts</code></td><td>El cuerpo del constructor: valores por defecto, logger, store + namespace y cada subsistema, en un orden fijo; construye el kernel y los módulos de abajo</td></tr><tr><td><code>kernel.ts</code></td><td><code>BotKernel</code>, los internos compartidos (subsistemas + estado del ciclo de vida) que recibe cada módulo, más pequeños helpers comunes</td></tr><tr><td><code>logger.ts</code></td><td>Adapta <code>BotConfig.logger</code> (pino, <code>console</code> o cualquier <code>{ debug, info, warn, error }</code>) al logger con <code>child()</code> que usan los módulos</td></tr><tr><td><code>lifecycle.ts</code></td><td><code>start()</code> / <code>stop()</code> como una lista ordenada de pasos, con rollback y drenado</td></tr><tr><td><code>inbound.ts</code></td><td>El flujo de eventos del provider → <code>fromMe</code> / filtro de ecos → listas de acceso → dedupe → persistencia → <code>groupMode</code> → Dispatcher; llamadas y eventos del provider (reacciones, recibos…)</td></tr><tr><td><code>outbound.ts</code></td><td>Envíos y ediciones por los hooks de <code>send</code>, el registro de mensajes, respuestas pausadas, typing y <code>ctx.stream()</code></td></tr><tr><td><code>presence.ts</code></td><td>La política de presencia sin conexión: <code>typing</code> / <code>markRead</code> se omiten (log en debug + <code>metrics().presenceSkipped</code>) mientras el transporte no está <code>&#39;ready&#39;</code></td></tr><tr><td><code>rateLimitRetry.ts</code></td><td>El reintento corto en el sitio de las respuestas de <code>ctx</code> limitadas por tasa (<code>BotConfig.rateLimitRetry</code>)</td></tr><tr><td><code>contextFactory.ts</code></td><td>Construye el <code>MessageContext</code> (<code>ctx</code>) de un mensaje, una llamada proyectada o un <code>bot.trigger()</code></td></tr><tr><td><code>interactionAck.ts</code></td><td>La única confirmación automática de una interacción en un transporte con <code>interactionsRequireAck</code> (Discord): antes del primer envío, cerca de <code>respondBy</code> o al terminar el enrutado</td></tr><tr><td><code>gates.ts</code></td><td>Admisión por listas de acceso y handoff a humano, con sus contadores y logs de descarte</td></tr><tr><td><code>handover.ts</code></td><td><code>coordination.handover</code> (solo con <code>coordination</code>): guarda la respuesta de un paso de flow en su checkpoint y la reconstruye en la réplica que toma el chat</td></tr><tr><td><code>lang.ts</code></td><td>La resolución de <code>ctx.lang</code> y los puntos de idioma del Dispatcher</td></tr><tr><td><code>persistence.ts</code></td><td>Escrituras de chat / contacto / handoff, ordenadas por chat</td></tr><tr><td><code>events.ts</code></td><td>La salida de errores y eventos de observabilidad</td></tr><tr><td><code>routes.ts</code></td><td><code>when</code>, <code>conversation</code>, <code>command</code>, <code>onMessage</code>, <code>onType</code>, hooks</td></tr><tr><td><code>pluginHost.ts</code></td><td><code>plug()</code>: un bot acotado cuyos registros se deshacen al desenchufar</td></tr><tr><td><code>ops.ts</code></td><td><code>trigger</code>, <code>triggerFlow</code>, <code>broadcast</code>, métricas, inventario de flujos, colaboradores de datos de sujeto</td></tr></tbody></table><p>Tres reglas lo mantienen en pie:</p><ul><li><strong>Sin campos <code>#private</code> en <code>Bot</code>.</strong> Un plugin recibe <code>Object.create(bot)</code> como <code>ctx.bot</code>; sus métodos corren con <code>this</code> apuntando a ese objeto, y leer un <code>#private</code> a través de él lanzaría. Al kernel se llega por <code>this</code>, o sea, por el prototipo.</li><li><strong>Enlaces tardíos.</strong> Los módulos llaman de vuelta al bot con closures (<code>bot.emit</code>, <code>bot.trigger</code>, <code>bot.isHandedOff</code>…) que se leen en el momento de la llamada, así que se respeta un spy, un override de subclase o el de un bot de plugin instalado después.</li><li><strong>El comportamiento va en un módulo, no en la fachada.</strong> Cada módulo tiene menos de 500 líneas y abre con un comentario que dice qué hace y qué no.</li></ul><h2 id="pipeline-de-entrada" tabindex="-1">Pipeline de entrada <a class="header-anchor" href="#pipeline-de-entrada" aria-label="Permalink to &quot;Pipeline de entrada&quot;">​</a></h2><p>Las cajas punteadas solo existen cuando su función está configurada.</p>',13)),d(a,{code:"flowchart%20TD%0A%20%20%20%20P%5B%22Evento%20del%20provider%22%5D%20--%3E%20K%7B%22%C2%BFmensaje%20%2F%20interacci%C3%B3n%3F%22%7D%0A%20%20%20%20K%20--%3E%7C%22llamada%22%7C%20CALL%5B%22Listas%20de%20acceso%20%2B%20handoff%20%E2%86%92%20hooks%20y%20evento%20'call'%20%E2%86%92%20triggers%20CALL%20(dispatchEvent)%22%5D%0A%20%20%20%20K%20--%3E%7C%22reacci%C3%B3n%2C%20encuesta%2C%20grupo%2C%20presencia%2C%20estado%22%7C%20HE%5B%22hooks%20before%2Fafter%20%2B%20evento%20del%20bot%22%5D%0A%20%20%20%20K%20--%3E%7C%22s%C3%AD%22%7C%20FM%7B%22%C2%BFfromMe%20%2F%20eco%20de%20un%20env%C3%ADo%20del%20bot%3F%22%7D%0A%20%20%20%20FM%20--%3E%7C%22s%C3%AD%22%7C%20X0%5B%22Descartado%20(fromMe%3B%20eco%3A%20dropped.echo)%22%5D%0A%20%20%20%20FM%20--%3E%7C%22no%22%7C%20ACL%7B%22Listas%20de%20acceso%22%7D%0A%20%20%20%20ACL%20--%3E%7C%22bloqueado%22%7C%20X1%5B%22Descartado%20(dropped.blocked)%22%5D%0A%20%20%20%20ACL%20--%3E%7C%22permitido%22%7C%20DD%7B%22Dedupe%3A%20chatId%20%2B%20id%22%7D%0A%20%20%20%20DD%20--%3E%7C%22ya%20visto%22%7C%20X2%5B%22Descartado%20(dropped.duplicate)%22%5D%0A%20%20%20%20DD%20--%3E%7C%22nuevo%22%7C%20DUR%5B%22Inbox%20durable%3A%20registra%20el%20evento%22%5D%0A%20%20%20%20DUR%20--%3E%20PER%5B%22Persistir%20chat%2C%20contacto%2C%20mensaje%22%5D%0A%20%20%20%20PER%20--%3E%20GM%7B%22groupMode%22%7D%0A%20%20%20%20GM%20--%3E%7C%22ignorado%22%7C%20X3%5B%22Se%20detiene%20(ya%20persistido)%22%5D%0A%20%20%20%20GM%20--%3E%7C%22ok%22%7C%20Q%5B%22Cola%20FIFO%20por%20chat%22%5D%0A%20%20%20%20Q%20--%3E%20TURN%5B%22Turno%20del%20chat%20entre%20r%C3%A9plicas%22%5D%0A%20%20%20%20TURN%20--%3E%20D%5B%22Dispatcher%3A%20idioma%20%E2%86%92%20before('message')%20%E2%86%92%20gate%20de%20handoff%20%E2%86%92%20comando%20%E2%86%92%20conversaci%C3%B3n%20activa%20%E2%86%92%20reanudaci%C3%B3n%20dormida%20%E2%86%92%20matchers%20%E2%86%92%20catch-all%20%E2%86%92%20after('message')%20%2B%20evento%20'message'%22%5D%0A%20%20%20%20style%20DUR%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20TURN%20stroke-dasharray%3A%205%205%0A"}),e[1]||(e[1]=o('<p>Las etapas de enrutado dentro del Dispatcher, en orden, están en <a href="/botmesh/es/guide/conceptos">Conceptos básicos</a>. Dos entradas se saltan parte de este camino: las <strong>llamadas</strong> pasan por las mismas listas de acceso y el handoff y solo llegan a triggers de tipo <code>CALL</code>, y <strong><code>bot.trigger()</code></strong> pasa por las listas de acceso, toma el turno del chat en la cola (<code>runExclusive</code>), el gate de handoff y la resolución de idioma, y arranca la conversación directamente: sin dedupe, persistencia, hooks de mensaje ni matchers.</p><h2 id="pipeline-de-salida" tabindex="-1">Pipeline de salida <a class="header-anchor" href="#pipeline-de-salida" aria-label="Permalink to &quot;Pipeline de salida&quot;">​</a></h2>',2)),d(a,{code:"flowchart%20TD%0A%20%20%20%20S%5B%22ctx.reply%20%2F%20bot.send%20%2F%20broadcast%22%5D%20--%3E%20PACE%5B%22Pacer%20(respuestas%20de%20texto%20de%20ctx)%3A%20retardo%20%2B%20typing%22%5D%0A%20%20%20%20PACE%20--%3E%20IDEM%5B%22Consulta%20de%20idempotencia%20durable%22%5D%0A%20%20%20%20IDEM%20--%3E%7C%22ya%20enviado%22%7C%20PRIOR%5B%22Se%20responde%20desde%20el%20outbox%20(sin%20hooks%20ni%20llamada%20al%20provider)%22%5D%0A%20%20%20%20IDEM%20--%3E%7C%22nuevo%22%7C%20BS%7B%22hooks%20before('send')%22%7D%0A%20%20%20%20BS%20--%3E%7C%22abort()%22%7C%20SK%5B%22skipped%3A%20true%22%5D%0A%20%20%20%20BS%20--%3E%7C%22sigue%22%7C%20FENCE%5B%22Fencing%20de%20r%C3%A9plica%3A%20esta%20r%C3%A9plica%20tiene%20el%20turno%20del%20chat%20%2F%20la%20sesi%C3%B3n%22%5D%0A%20%20%20%20FENCE%20--%3E%20OB%5B%22Outbox%20durable%3A%20registra%20el%20env%C3%ADo%22%5D%0A%20%20%20%20OB%20--%3E%20PS%5B%22provider.send%22%5D%0A%20%20%20%20PS%20--%3E%7C%22ok%22%7C%20AS%5B%22m%C3%A9tricas%20%E2%86%92%20after('send')%20%E2%86%92%20registro%20de%20mensajes%20(sent)%22%5D%0A%20%20%20%20PS%20--%3E%7C%22diferido%22%7C%20SW%5B%22El%20barrido%20del%20outbox%20lo%20entrega%20despu%C3%A9s%22%5D%0A%20%20%20%20PS%20--%3E%7C%22error%22%7C%20FAIL%5B%22registro%20de%20mensajes%20(failed)%20%E2%86%92%20error%20a%20quien%20llam%C3%B3%22%5D%0A%20%20%20%20style%20PACE%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20IDEM%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20FENCE%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20OB%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20SW%20stroke-dasharray%3A%205%205%0A"}),e[2]||(e[2]=o('<p><code>ctx.edit()</code> sigue el mismo camino con <code>edit</code> en el payload del hook. Las vistas previas en vivo de <code>ctx.stream()</code> (borradores y ediciones en el sitio) solo corren los hooks <code>before(&#39;send&#39;)</code>; los mensajes que el stream envía al final siguen el camino completo. <code>bot.enqueue()</code> (solo con durabilidad) corre los hooks <code>before(&#39;send&#39;)</code>, registra el envío y vuelve enseguida; lo entrega el barrido del outbox.</p><h2 id="ciclo-de-vida" tabindex="-1">Ciclo de vida <a class="header-anchor" href="#ciclo-de-vida" aria-label="Permalink to &quot;Ciclo de vida&quot;">​</a></h2>',2)),d(a,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20start%5B%22start()%22%5D%0A%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20A1%5B%22storage%22%5D%20--%3E%20A2%5B%22coordinaci%C3%B3n%22%5D%20--%3E%20A3%5B%22restaurar%20conversaciones%20%2B%20handoffs%22%5D%20--%3E%20A4%5B%22durabilidad%3A%20recuperar%22%5D%20--%3E%20A5%5B%22transporte%22%5D%20--%3E%20A6%5B%22jobs%20(scheduler)%22%5D%0A%20%20%20%20end%0A%20%20%20%20style%20A2%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20A4%20stroke-dasharray%3A%205%205%0A"}),e[3]||(e[3]=o('<p><code>stop()</code> cierra la entrada y cancela los broadcasts, emite <code>&#39;stopping&#39;</code> (ahí los plugins cancelan el trabajo largo; <code>@botmesh/ai</code> aborta sus llamadas al modelo), detiene o pausa los pasos que producen trabajo nuevo (scheduler, barrido de durabilidad), opcionalmente drena los envíos en curso (<code>stop({ drain: true })</code>), cierra los envíos pausados y aborta las conversaciones (los checkpoints se conservan), y después detiene el resto de pasos en orden inverso (el paso <code>storage</code> deja antes que terminen, hasta 5 s, los envíos en vuelo y las filas del log de los envíos que el provider ya aceptó, y luego cierra el store). Si <code>start()</code> falla, los pasos ya arrancados se deshacen en orden inverso y el error se relanza.</p><p>Una función opcional añade un <strong>paso de ciclo de vida</strong>; no reparte <code>if</code>s por el código de arranque y parada.</p><h2 id="donde-se-enchufan-las-funciones-opcionales" tabindex="-1">Dónde se enchufan las funciones opcionales <a class="header-anchor" href="#donde-se-enchufan-las-funciones-opcionales" aria-label="Permalink to &quot;Dónde se enchufan las funciones opcionales&quot;">​</a></h2><p>Todas vienen apagadas. Un bot que no las configura corre exactamente el camino descrito arriba sin las cajas punteadas.</p><table tabindex="0"><thead><tr><th>Función</th><th>Config</th><th>Etapas que toca</th><th>Guía</th></tr></thead><tbody><tr><td>Procesamiento durable</td><td><code>durability</code></td><td>Entrada: registra cada evento en un <strong>inbox</strong> antes de despacharlo y lo confirma cuando el trabajo que inició termina; lo reproduce tras una caída. Salida: consulta de idempotencia y un registro en el <strong>outbox</strong> por envío, con reintentos y cola de muertos. Ciclo de vida: un paso <code>durability</code></td><td><a href="/botmesh/es/guide/durabilidad">Procesamiento durable</a></td></tr><tr><td>Coordinación entre réplicas</td><td><code>coordination</code></td><td>Entrada: cada chat se procesa bajo un <strong>turno</strong> entre réplicas, en orden de llegada. Salida: un <strong>fencing</strong> rechaza envíos de una réplica que perdió su turno o la sesión del provider. Ciclo de vida: un paso <code>coordination</code> y elección de líder para transportes exclusivos. Con <code>coordination.handover</code>, los checkpoints de flow guardan la respuesta de un paso cortado y los flows no persistentes pueden pasar a otra réplica</td><td><a href="/botmesh/es/guide/replicas">Varias réplicas</a></td></tr><tr><td>Scheduler durable</td><td><code>scheduler</code></td><td>Jobs: las tareas con <code>id</code> se guardan, sobreviven a reinicios con una política de ejecuciones perdidas y cada ocurrencia corre en una sola réplica (un <strong>lease</strong>)</td><td><a href="/botmesh/es/guide/scheduler">Scheduler</a></td></tr><tr><td>Trazas</td><td><code>telemetry</code></td><td>Envuelve en spans las etapas que observa sin cambiar su orden ni sus tiempos: evento del provider (<code>bot.inbound</code>), persistencia, despacho, handler, cada turno de conversación entre esperas, el pacing y cada envío; <code>@botmesh/ai</code> añade spans de modelo y herramientas. <code>@botmesh/otel</code> (fuera del core, con <code>@opentelemetry/api</code> como peer opcional) los exporta. Cada ejecución de una tarea programada es un span raíz <code>bot.task</code>, y una conversación retomada en otra réplica (o tras un reinicio) enlaza su primer turno al turno que escribió el checkpoint (<code>FlowCheckpoint.trace</code>, W3C)</td><td><a href="/botmesh/es/guide/trazas">Trazas</a></td></tr></tbody></table><h2 id="ver-tambien" tabindex="-1">Ver también <a class="header-anchor" href="#ver-tambien" aria-label="Permalink to &quot;Ver también&quot;">​</a></h2><ul><li><a href="/botmesh/es/guide/conceptos">Conceptos básicos</a>: el orden completo de enrutado y las conversaciones.</li><li><a href="/botmesh/es/guide/hooks">Hooks</a>: los contratos de los hooks <code>message</code> y <code>send</code>.</li><li><a href="/botmesh/es/guide/plugins">Plugins</a>: qué registra y deshace un bot de plugin.</li></ul>',7))])}const A=t(n,[["render",i]]);export{g as __pageData,A as default};
